//! 🧪️ Native envelope fields move without serialization through genuine one-fuel caller turns and cancellation.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn observe<T>(run:impl FnOnce()->T)->(T,usize,usize){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(v,h.requested_bytes,h.released_bytes)}
fn run(caller:&mut OriginalJobFixtureCaller,g:RetainedCloneGrant,births:&mut usize,releases:&mut usize,body:impl FnOnce(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>){let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(1,1500,body)).unwrap());let p=caller.receipt();assert!(p.fits(g));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));*births+=born;*releases+=free}
fn kind(outcome:&FlowReplyEnvelope)->&'static str{match outcome{FlowReplyEnvelope::Complete{..}=>"complete",FlowReplyEnvelope::Pending{..}=>"pending",FlowReplyEnvelope::Working(_)=>"working",FlowReplyEnvelope::Cancelled(_)=>"cancelled"}}
fn pointer(value:&DslValue)->Option<usize>{let row=rows(value).ok()?;if let Some((_,DslValue::Object(value)))=row.iter().find(|(key,_)|key=="output"){return Some(value.as_ptr()as usize)}let pending=row.iter().find(|(key,_)|key=="pending")?;let value=rows(&pending.1).ok()?.iter().find(|(key,_)|key=="neuronId")?;Some(text(&value.1).ok()?.as_ptr()as usize)}
#[test]
fn original_native_flow_reply_preserves_output_and_pending_allocations_under_one_fuel_and_cancel(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️envelope.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};
 for row in fixture["cases"].as_array().unwrap(){for stop in [None,Some(0),Some(1),Some(7),Some(13)]{
  let wire=serde_json::to_string(&row["envelope"]).unwrap();let((mut work,original_pointer),born,free)=observe(||{let original: DslValue=semio_framework_pack_json::from_json_str(&wire,semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let pointer=pointer(&original);(FlowReplyEnvelopeWork::new(original),pointer)});let original=born-free;let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);let mut actual=None;let mut failure=None;
  for call in 0..200{if stop==Some(call){break}run(&mut caller,RetainedCloneGrant{maximum_items:0,..stock},&mut births,&mut releases,|cx|{assert!(work.step(cx)?.is_none());Ok(())});run(&mut caller,stock,&mut births,&mut releases,|cx|{match work.step(cx){Ok(value)=>actual=value,Err(error)=>failure=Some(error)}Ok(())});if actual.is_some()||failure.is_some(){break}}
  let agrees=if stop.is_none(){match actual.as_ref(){Some(value)=>Some(kind(value))==row["expected"].as_str(),None=>failure.is_some()&&row["expected"]=="refusal"}}else{true};
  let custody=match actual.as_ref(){Some(FlowReplyEnvelope::Complete{output:DslValue::Object(value),..})=>Some(value.as_ptr()as usize)==original_pointer,Some(FlowReplyEnvelope::Pending{pending:value,..})=>Some(value.neuron_id.as_ptr()as usize)==original_pointer,_=>true};
  if stop.is_some(){caller.cancel().cancel_now();run(&mut caller,stock,&mut births,&mut releases,|cx|{assert!(work.step(cx)?.is_none());Ok(())});assert_eq!(caller.receipt(),Default::default());}
  work.begin_close();for _ in 0..100000{if work.terminal_is_empty(){break}let d=work.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|work.close_step(cx).map(|_|())))}assert!(work.terminal_is_empty());
  let mut retained=ControlledRetirement::new((actual,failure)).unwrap_or_else(|_|unreachable!("native envelope and exact refusal have physical retirement"));for _ in 0..100000{if retained.terminal_is_empty(){break}let d=retained.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|{let result=retained.step(g);RetainedWorkOutcome{result,work:retained.last_turn_work()}})?;Ok(())}))}assert!(retained.terminal_is_empty());assert_eq!(original+births,releases);caller.retire(stock);assert!(agrees&&custody,"native envelope must retain canonical values and exact original allocations");
 }}
}

#[derive(RetireOwned)]
struct ResumeSources{outer:flow::invocation_publication::FlowInvocationOrigin,child:flow::invocation_publication::FlowInvocationOrigin,output:DslValue}
fn native_origin(row:&serde_json::Value,outer:Option<u64>)->flow::invocation_publication::FlowInvocationOrigin{let text=|key|row[key].as_str().unwrap().to_owned();flow::invocation_publication::FlowInvocationOrigin{window_id:text("windowId"),window_kind_id:text("windowKindId"),neuron_id:text("neuronId"),extension_id:text("extensionId"),operator_id:text("operatorId"),node_hash:row["nodeHash"].as_u64().unwrap(),input_json:text("inputJson"),dependency_json:row.get("dependencyJson").and_then(serde_json::Value::as_str).unwrap_or("").to_owned(),operator_version:row.get("operatorVersion").and_then(serde_json::Value::as_str).unwrap_or("").to_owned(),outer_node_hash:outer,preview_source:None}}
#[test]
fn original_external_resume_keeps_native_output_and_original_origins_under_one_fuel_and_cancel(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️envelope.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};
 for row in fixture["resumeCases"].as_array().unwrap(){for stop in [None,Some(0),Some(3),Some(17)]{
  let((sources,mut work),born,free)=observe(||{let outer=native_origin(&row["outer"],None);let child=native_origin(&row["child"],Some(outer.node_hash));let output=semio_framework_pack_json::from_json_str(&serde_json::to_string(&row["output"]).unwrap(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();(ResumeSources{outer,child,output},super::resume::FlowExternalResumeRequestWork::new())});let original=born-free;let pointers=(sources.outer.input_json.as_ptr(),sources.outer.dependency_json.as_ptr(),sources.child.neuron_id.as_ptr());let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);let mut actual=None;let mut syntax=None;let mut failure=None;let mut calls=0;
  for call in 0..200{if stop==Some(call){break}calls=call+1;run(&mut caller,RetainedCloneGrant{maximum_items:0,..stock},&mut births,&mut releases,|cx|{assert!(work.step(&sources.outer,&sources.child,&sources.output,&mut syntax,cx)?.is_none());Ok(())});run(&mut caller,stock,&mut births,&mut releases,|cx|{match work.step(&sources.outer,&sources.child,&sources.output,&mut syntax,cx){Ok(value)=>actual=value,Err(error)=>failure=Some(error)}Ok(())});if actual.is_some()||syntax.is_some()||failure.is_some(){break}}
  let agrees=stop.is_some()||actual.as_ref().is_some_and(|wire|serde_json::from_str::<serde_json::Value>(wire).unwrap()==row["expected"]);let kept=pointers==(sources.outer.input_json.as_ptr(),sources.outer.dependency_json.as_ptr(),sources.child.neuron_id.as_ptr());
  if stop.is_some()&&actual.is_none()&&syntax.is_none()&&failure.is_none(){caller.cancel().cancel_now();run(&mut caller,stock,&mut births,&mut releases,|cx|{assert!(work.step(&sources.outer,&sources.child,&sources.output,&mut syntax,cx)?.is_none());Ok(())});assert_eq!(caller.receipt(),Default::default());}
  work.begin_close();for _ in 0..100000{if work.terminal_is_empty(){break}let d=work.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|work.close_step(cx).map(|_|())))}assert!(work.terminal_is_empty());
  let mut retained=ControlledRetirement::new(((sources,actual),(syntax,failure))).unwrap_or_else(|_|unreachable!("native outer, child, output and codec refusal have full retirement"));for _ in 0..100000{if retained.terminal_is_empty(){break}let d=retained.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|{let result=retained.step(g);RetainedWorkOutcome{result,work:retained.last_turn_work()}})?;Ok(())}))}assert!(retained.terminal_is_empty());assert_eq!(original+births,releases);caller.retire(stock);assert!(agrees&&kept,"native externalResult retains the real child and original parent within unchanged opportunity; calls={calls}");
 }}
}

#[test]
fn original_keyed_reply_settlement_preserves_last_answer_and_abandonment(){
 use flow::original_window_latch::{FlowEvalWindowTickLatch,FlowWindowLatches,settle_flow_window_reply,flow_window_publication_demands};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️envelope.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};
 for row in fixture["latches"].as_array().unwrap(){let key=flow::FlowEvalWindowKey::cold("main");let before=&row["before"];let state=FlowEvalWindowTickLatch{armed:before["armed"].as_bool().unwrap(),in_flight:u32::try_from(before["inFlight"].as_u64().unwrap()).unwrap(),owed:before["owed"].as_bool().unwrap(),unfinished:before["unfinished"].as_bool().unwrap()};let(mut latches,born,free)=observe(||[(key.fingerprint(),state)].into_iter().collect::<FlowWindowLatches>());let original=born-free;let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);let give_up=row["giveUp"].as_bool().unwrap();let mut armed=false;
  run(&mut caller,RetainedCloneGrant{maximum_items:0,..stock},&mut births,&mut releases,|cx|{let turn=settle_flow_window_reply(&mut latches,key,give_up,cx.retained_grant());assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().1,Default::default());assert_eq!(latches.get(&key.fingerprint()),Some(&state));Ok(())});
  let d=flow_window_publication_demands();run(&mut caller,stock,&mut births,&mut releases,|cx|{assert!(cx.retained_work_can_enter(d));let turn=settle_flow_window_reply(&mut latches,key,give_up,RetainedCloneGrant{maximum_items:1,..cx.retained_grant()});let result=turn.result.map(|(actual,p)|{armed=actual;RetainedCloneStep::Complete(p)});semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;Ok(())});
  let actual=latches.get(&key.fingerprint()).unwrap();let matches=serde_json::json!({"armed":actual.armed,"inFlight":actual.in_flight,"owed":actual.owed,"unfinished":actual.unfinished})==row["expected"]&&armed==row["emitTick"].as_bool().unwrap();
  let mut retained=ControlledRetirement::new(latches).unwrap_or_else(|_|unreachable!("the same Copy-keyed latch arena has native retirement"));for _ in 0..100000{if retained.terminal_is_empty(){break}let d=retained.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|{let result=retained.step(g);RetainedWorkOutcome{result,work:retained.last_turn_work()}})?;Ok(())}))}assert!(retained.terminal_is_empty());assert_eq!(original+births,releases);caller.retire(stock);assert!(matches);
 }
}


#[test]
fn original_reply_progress_extraction_keeps_other_rows_and_closes_actual_sources(){
 use flow::{FlowEvalSession,FlowEvaluationReplyReceiver,FlowEvaluationReplyAddress};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️envelope.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};
 for row in fixture["progressClears"].as_array().unwrap(){
  let(mut session,born,free)=observe(FlowEvalSession::new);let original=born-free;let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);
  for hash in row["before"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()){
   let mut receiver=None;run(&mut caller,stock,&mut births,&mut releases,|cx|{receiver=Some(FlowEvaluationReplyReceiver::from_native_parts(PreviewEvalProgress{units_done:0,units_total:1,phase:PreviewEvalPhase::Computing},false,true,None,cx).map_err(|(error,_)|error)?);Ok(())});let mut receiver=receiver.unwrap();let address=FlowEvaluationReplyAddress{node_hash:hash,window_id:"main",window_kind_id:"main"};let mut ready=false;
   for _ in 0..200{run(&mut caller,stock,&mut births,&mut releases,|cx|{ready=receiver.step(&mut session,&address,cx)?;Ok(())});if ready{break}}assert!(ready);receiver.begin_close();
   for _ in 0..100000{if receiver.terminal_is_empty(){break}let d=receiver.next_close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|receiver.close_step(cx).map(|_|())))}assert!(receiver.terminal_is_empty());
  }
  let hash=row["hash"].as_u64().unwrap();let mut slot=0;let mut displaced=None;let mut ready=false;
  run(&mut caller,RetainedCloneGrant{maximum_items:0,..stock},&mut births,&mut releases,|cx|{let turn=session.clear_reply_progress_original(hash,&mut slot,&mut displaced,cx.retained_grant());assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap(),(false,Default::default()));assert_eq!(slot,0);assert!(displaced.is_none());Ok(())});
  for _ in 0..200{run(&mut caller,RetainedCloneGrant{maximum_items:512,..stock},&mut births,&mut releases,|cx|{let d=session.reply_progress_clear_demands(slot)?;if !cx.retained_work_can_enter(d){return Ok(())}let turn=session.clear_reply_progress_original(hash,&mut slot,&mut displaced,RetainedCloneGrant{maximum_items:1,..cx.retained_grant()});assert!(turn.work<=1);let result=turn.result.map(|(done,p)|{ready=done;RetainedCloneStep::Complete(p)});semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;Ok(())});if ready{break}}
  let matches=ready&&!session.has_evaluation_progress(hash)&&row["expected"].as_array().unwrap().iter().all(|hash|session.has_evaluation_progress(hash.as_u64().unwrap()));let mut close=ControlledRetirement::new(displaced).unwrap_or_else(|_|unreachable!("the actual extracted Copy row has full retirement"));
  for _ in 0..100000{if close.terminal_is_empty(){break}let d=close.selected_demand(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|{let result=close.step(g);RetainedWorkOutcome{result,work:close.last_turn_work()}})?;Ok(())}))}assert!(close.terminal_is_empty());session.begin_close();
  for _ in 0..100000{if session.terminal_is_empty(){break}let copy=session.next_close_copy_byte_demand().unwrap();let d=RetirementDemand{copy_bytes:copy,capacity_bytes:session.next_close_capacity_byte_demand(copy).unwrap(),release_bytes:session.next_close_release_byte_demand().unwrap(),depth:session.next_close_depth_demand().unwrap()};let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};run(&mut caller,g,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|session.retire_source_step(g))?;Ok(())}))}let closed=session.terminal_is_empty();drop(session);assert!(closed);assert_eq!(original+births,releases);caller.retire(stock);assert!(matches);
 }
}
